        modelKey: input.modelKey,
        providerModelIdentifier: input.providerModelIdentifier,
        status: "active",
        capabilities: input.capabilities ?? {},
        contextWindow: input.contextWindow ?? null,
        metadata: input.metadata ?? {},
        createdAt: now,
        updatedAt: now
