// src/server/pre-analyses/audit.ts
async function auditPreAnalysis(core, actor, organizationId, action, metadata = {}) {
  await core.addAuditEvent({
    id: core.nextId("aud"),
    organizationId,
    actorUserId: actor.kind === "user" ? actor.userId : null,
    action,
    result: "allowed",
    reason: null,
    metadata,
    createdAt: core.now()
  });
}
async function auditPreAnalysisDenied(core, actor, organizationId, action, reason, metadata = {}) {
  await core.addAuditEvent({
    id: core.nextId("aud"),
    organizationId,
    actorUserId: actor.kind === "user" ? actor.userId : null,
    action,
    result: "denied",
    reason,
    metadata,
    createdAt: core.now()
  });
}
async function auditPreAnalysisSystem(core, organizationId, action, metadata = {}) {
  await core.addAuditEvent({
    id: core.nextId("aud"),
    organizationId,
    actorUserId: null,
    action,
    result: "allowed",
    reason: null,
    metadata,
    createdAt: core.now()
  });
}

// src/server/pre-analyses/transaction.ts
function createPreAnalysisTransactionRunner(pool) {
  return async (callback) => {
    const client = await pool.connect();
    try {
      await client.query("BEGIN");
      const result = await callback({
        core: new PostgresCoreRepository(client, true),
        preAnalyses: new PostgresPreAnalysisRepository(client),
        candidateApplications: new PostgresCandidateApplicationRepository(client)
      });
      await client.query("COMMIT");
      return result;
    } catch (error) {
      await client.query("ROLLBACK");
      throw error;
    } finally {
      client.release();
    }
  };
}

