// src/server/pre-analyses/validation.ts
function validateId5(value, field) {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw badRequest(`pre_analysis_${field}_invalid`, `${field} is required.`);
  }
  return value;
}
function validateRequestInput(input) {
  const candidateApplicationId = validateId5(
    input.candidateApplicationId ?? input.candidate_application_id,
    "candidate_application_id"
  );
  return { candidateApplicationId };
}
function validateReasonInput3(input) {
  const reason = input.reason;
  if (typeof reason !== "string" || reason.trim().length < 3 || reason.length > 1e3) {
    throw badRequest(
      "pre_analysis_reason_invalid",
      "A reason between 3 and 1000 characters is required."
    );
  }
  return reason;
}
function validateAdminReadInput(input) {
  return validateReasonInput3(input);
}

